/**
 * Strict PII and Secrets Scanner
 *
 * Requirements:
 * - Scans fixtures, seed data, build output, and repository files.
 * - Allows ONLY numbers generated by the reserved synthetic generator: /^5\d{9}$/.
 * - Any 10-digit number matching Indian mobile subscriber series ([6-9]\d{9}) fails the scan.
 * - Detects session cookies and live JWT tokens / secrets.
 * - NEVER prints detected sensitive values into console or CI logs.
 * - Fails with exit code 1 if violations are found.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');

const SYNTHETIC_PHONE_REGEX = /^5\d{9}$/;

const IGNORED_DIRS = new Set([
  'node_modules',
  '.git',
  '.wxt',
  'cache',
]);

const IGNORED_EXTENSIONS = new Set([
  '.png',
  '.jpg',
  '.jpeg',
  '.ico',
  '.gif',
  '.webp',
  '.zip',
  '.lock',
  '.map',
  '.pack',
  '.tsbuildinfo',
  '.rscinfo',
  '.previewinfo',
]);

const VIOLATIONS = [];

function isInsideUuid(lineText, index) {
  const start = Math.max(0, index - 30);
  const end = Math.min(lineText.length, index + 30);
  const snippet = lineText.slice(start, end);
  return /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i.test(snippet);
}

export function scanContent(content, filePath = 'mock-file.txt') {
  const fileViolations = [];
  const lines = content.split('\n');

  lines.forEach((lineText, idx) => {
    const lineNum = idx + 1;

    // 1. Check for live JWT tokens (allow mock short tokens in tests)
    if (/Bearer\s+eyJ[A-Za-z0-9_.-]{50,}/i.test(lineText)) {
      fileViolations.push({ file: filePath, line: lineNum, rule: 'Live JWT / Bearer Token detected' });
    }

    // 2. Check for unmasked session cookies
    if (/(?:connect\.sid|sb-[a-z0-9]+-auth-token)\s*=\s*[a-zA-Z0-9_.-]{25,}/i.test(lineText)) {
      fileViolations.push({ file: filePath, line: lineNum, rule: 'Live Session Cookie detected' });
    }

    // 3. Global phone check: any Indian mobile subscriber series ([6-9]\d{9}) fails immediately
    const phoneRegex = /(?:\b|[^\da-fA-F])([6-9]\d{9})(?:\b|[^\da-fA-F])/g;
    let match;
    while ((match = phoneRegex.exec(lineText)) !== null) {
      if (isInsideUuid(lineText, match.index)) {
        continue;
      }
      fileViolations.push({ file: filePath, line: lineNum, rule: 'Real Indian mobile number pattern [6-9]xxxxxxxxx detected' });
      break;
    }

    // 4. Fixture-specific Allowlist Validation:
    // Every identifier, customer number, and merchant name in fixtures must come strictly from generator patterns
    const isFixtureFile = filePath.includes(path.sep + 'fixtures' + path.sep) || filePath.startsWith('fixtures/');
    if (isFixtureFile && !lineText.includes('printData.') && !lineText.includes('site_data.')) {
      // Whitelist check: Any 10-digit number must be synthetic (5xxxxxxxxx)
      const tenDigitRegex = /(?:\b|[^\da-zA-Z])(\d{10})(?:\b|[^\da-zA-Z])/g;
      let m;
      while ((m = tenDigitRegex.exec(lineText)) !== null) {
        if (!SYNTHETIC_PHONE_REGEX.test(m[1])) {
          fileViolations.push({ file: filePath, line: lineNum, rule: 'Non-allowlisted 10-digit customer number in fixture' });
        }
      }

      // Whitelist check: SimpleWallet transaction numbers (8 digits in table or TransNo param)
      const transNoMatch = /(?:<td>(\d{8})<\/td>|TransNo=(\d+))/i.exec(lineText);
      if (transNoMatch) {
        const val = transNoMatch[1] || transNoMatch[2];
        if (!/^55\d{6}$/.test(val)) {
          fileViolations.push({ file: filePath, line: lineNum, rule: 'Non-allowlisted SimpleWallet transaction number in fixture' });
        }
      }

      // Whitelist check: EG Payment Order ID
      const orderMatch = /Order ID:\s*([^\s<]+)/i.exec(lineText);
      if (orderMatch) {
        if (!/^555\d{11}$/.test(orderMatch[1])) {
          fileViolations.push({ file: filePath, line: lineNum, rule: 'Non-allowlisted EG Payment Order ID in fixture' });
        }
      }

      // Whitelist check: EG Payment Receipt link ID
      const receiptMatch = /\/transaction_receipt\/([^"?#\s<]+)/i.exec(lineText);
      if (receiptMatch) {
        if (!/^555\d{11}$/.test(receiptMatch[1])) {
          fileViolations.push({ file: filePath, line: lineNum, rule: 'Non-allowlisted EG Payment Receipt ID in fixture' });
        }
      }

      // Whitelist check: Operator reference (EG Payment or SimpleWallet)
      const oprRefMatch = /(?:Operator Ref\s*:\s*([^\s<]+)|OprTrnID=([^&"'\s]+))/i.exec(lineText);
      if (oprRefMatch) {
        const val = oprRefMatch[1] || oprRefMatch[2];
        if (!/^OPR\d{10}$/.test(val)) {
          fileViolations.push({ file: filePath, line: lineNum, rule: 'Non-allowlisted Operator Reference in fixture' });
        }
      }

      // Whitelist check: Retailer code and merchant header in SimpleWallet
      const retailerCodeMatch = /<b[^>]*>\s*([A-Za-z0-9_]+)\s*<\/b>\s*\|\s*([^<]+)/i.exec(lineText);
      if (retailerCodeMatch) {
        const code = retailerCodeMatch[1];
        const name = retailerCodeMatch[2].trim();
        if (!/^SYNRET\d{4}$/.test(code)) {
          fileViolations.push({ file: filePath, line: lineNum, rule: 'Non-allowlisted retailer code in fixture' });
        }
        if (!/^Demo Merchant \d+$/.test(name)) {
          fileViolations.push({ file: filePath, line: lineNum, rule: 'Non-allowlisted merchant name in fixture' });
        }
      }

      // Whitelist check: receivedBy parameter in receipt links
      const receivedByMatch = /receivedBy=([^&"'\n]+)/i.exec(lineText);
      if (receivedByMatch) {
        const decoded = decodeURIComponent(receivedByMatch[1]).trim();
        if (!/^Demo Merchant \d+$/.test(decoded)) {
          fileViolations.push({ file: filePath, line: lineNum, rule: 'Non-allowlisted merchant name in receipt link' });
        }
      }
    }
  });

  return fileViolations;
}

function scanFile(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  const baseName = path.basename(filePath);

  if (IGNORED_EXTENSIONS.has(ext)) return;
  if (baseName === 'trace' || baseName.startsWith('.cache')) return;

  // Skip self, generator definition, documentation of the generator, and simulated redaction unit tests
  if (
    filePath.endsWith('scan-pii-secrets.mjs') ||
    filePath.endsWith('SYNTHETIC_ALLOWLIST.md') ||
    filePath.endsWith('synthetic-generator.ts') ||
    filePath.endsWith('log-redaction.test.ts') ||
    filePath.endsWith('scanner.test.ts')
  ) {
    return;
  }

  let content = '';
  try {
    content = fs.readFileSync(filePath, 'utf8');
  } catch {
    return; // binary or unreadable
  }

  const fileViolations = scanContent(content, filePath);
  VIOLATIONS.push(...fileViolations);
}

function walkDir(dir) {
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (entry.isDirectory()) {
      if (!IGNORED_DIRS.has(entry.name)) {
        walkDir(path.join(dir, entry.name));
      }
    } else if (entry.isFile()) {
      scanFile(path.join(dir, entry.name));
    }
  }
}

export function runScan() {
  VIOLATIONS.length = 0;
  walkDir(rootDir);

  console.log(`\n=== Strict PII & Secrets Scan Completed ===`);
  console.log(`Target: ${rootDir}`);
  console.log(`Allowed Pattern: 5xxxxxxxxx (non-Indian mobile range)`);

  if (VIOLATIONS.length === 0) {
    console.log(`✓ 0 PII or real mobile subscriber number patterns found.\n`);
    return { success: true, violationsCount: 0 };
  }

  console.error(`\n❌ FOUND ${VIOLATIONS.length} VIOLATION(S):`);
  for (const v of VIOLATIONS) {
    const relPath = path.relative(rootDir, v.file);
    console.error(`  - [${v.rule}] in ${relPath}:${v.line}`);
  }
  console.error(`\nNote: Sensitive values are suppressed from this output for privacy.`);
  return { success: false, violationsCount: VIOLATIONS.length };
}

// Direct execution
if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { success } = runScan();
  if (!success) {
    process.exit(1);
  }
}
